(function(){const t=window.RQ=window.RQ||{};t.COMPANY={name:null,orgNr:null,vat:null,address:null,returnAddress:null,email:"support@rumiq.se"};const n=t.COMPANY,l=r=>`<span class="pending">${r}: fylls i innan f\xF6rs\xE4ljningen b\xF6rjar</span>`,d=()=>`${n.name||l("F\xF6retagsnamn")}, org.nr ${n.orgNr||l("organisationsnummer")}, ${n.address||l("adress")}`,i='<p class="draft">Utkast. Texten kontrolleras och kompletteras med bolags- och leverant\xF6rsuppgifter innan butiken \xF6ppnar.</p>',e=`<a href="mailto:${n.email}">${n.email}</a>`,o=window.RQ_CONFIG||{},s=o.delivery||{},p=o.shipping||{},a=t.facts={openDays:s.openPurchaseDays||0,minDays:s.minDays||0,maxDays:s.maxDays||0,freeFrom:o.freeShippingFrom||0,pickup:p.pickup||49,home:p.home||89},m=a.openDays?`${a.openDays} dagars \xF6ppet k\xF6p fr\xE5n att du tog emot varan. Lagen ger alltid 14 dagars \xE5ngerr\xE4tt.`:"Du har 14 dagars \xE5ngerr\xE4tt fr\xE5n att du tog emot varan.",g=a.minDays?`M\xE5let \xE4r ${a.minDays}\u2013${a.maxDays} arbetsdagar.`:"Leveranstiden visas innan du betalar.",u=`H\xE4mta hos ombud eller i paketsk\xE5p kostar ${a.pickup} kr och hemleverans ${a.home} kr.${a.freeFrom?` Handlar du f\xF6r ${a.freeFrom} kr eller mer \xE4r frakten till ombud och paketsk\xE5p fri.`:""}`;t.INFO={"sa-fungerar-det":{title:"S\xE5 fungerar RumIQ",kicker:"Fr\xE5n f\xF6rsta id\xE9 till f\xE4rdigt rum",lead:"Fem steg fr\xE5n att du hittar n\xE5got du gillar till att det st\xE5r hemma hos dig.",html:()=>`
        <ol class="steps-list">
          <li><h3>Uppt\xE4ck</h3><p>Bl\xE4ddra i butiken efter kategori eller rum, l\xE4s magasinet eller beskriv med egna ord vad du beh\xF6ver. Svep, Hitta r\xE4tt och stylisten f\xF6resl\xE5r produkter, och ingen av dem beh\xF6ver en bild.</p></li>
          <li><h3>Se det i ditt rum</h3><p>L\xE4gg till ett foto av ditt rum eller v\xE4lj ett exempelrum. V\xE4lj produkter och placera dem d\xE4r du vill ha dem. Resultatet \xE4r en bild att inspireras av, s\xE5 storlek och f\xE4rg kan skilja sig fr\xE5n verkligheten. Kontrollera alltid produktsidan.</p></li>
          <li><h3>Spara det du gillar</h3><p>Under Sparat samlar du produkter, dina rumsprojekt och din stil, s\xE5 att du kan forts\xE4tta d\xE4r du slutade.</p></li>
          <li><h3>Best\xE4ll tryggt</h3><p>L\xE4gg enskilda produkter eller en hel look i varukorgen och betala i Shopifys s\xE4kra kassa. Leveranss\xE4tt, kostnad och ber\xE4knad leveranstid visas innan du betalar. Vi ser aldrig dina kortuppgifter.</p></li>
          <li><h3>Leverans och hj\xE4lp</h3><p>F\xF6lj din best\xE4llning, t\xE4nk p\xE5 att varor kan komma i olika paket och h\xF6r av dig om n\xE5got inte st\xE4mmer. ${m}</p></li>
        </ol>
        <h2>Verktygen</h2>
        <p>Alla verktyg \xE4r gratis. Studio Plus \xE4r ett tillval f\xF6r dig som vill ha fler AI-bilder.</p>
        <table class="tbl"><thead><tr><th>Verktyg</th><th>Vad det g\xF6r</th><th>Konto</th></tr></thead><tbody>
          <tr><td><a href="#svep">Svep</a></td><td>Svep tio kort eller g\xF6r fyra snabba val och f\xE5 din stilprofil.</td><td>Beh\xF6vs inte</td></tr>
          <tr><td><a href="#mitt-rum">Mitt rum</a></td><td>Se produkterna i ett foto av ditt rum, dag som kv\xE4ll, och se vad som passar f\xE4rgerna d\xE4r.</td><td>Beh\xF6vs inte</td></tr>
          <tr><td><a href="#hitta-ratt">Hitta r\xE4tt</a></td><td>Till ditt hem, som present eller med egna ord. Stylisten finns ett tryck bort.</td><td>Beh\xF6vs inte</td></tr>
          <tr><td><a href="#looks">Looks</a></td><td>Looks med rabatt, eller bygg din egen.</td><td>Beh\xF6vs inte</td></tr>
          <tr><td><a href="#mitt-hem">Sparat</a></td><td>Det du sparat, dina rum och m\xE5tt, din stil och dina projekt p\xE5 ett st\xE4lle.</td><td>Sparas i din webbl\xE4sare</td></tr>
        </tbody></table>
        <p class="note">Verktygens resultat \xE4r f\xF6rslag, inte garantier eller produktfakta. Kontrollera alltid m\xE5tt, material och pris p\xE5 produktsidan innan du k\xF6per.</p>`},frakt:{title:"Frakt & leverans",kicker:"Kundservice",lead:"S\xE5 kommer dina saker hem till dig, och vad som g\xE4ller om n\xE5got dr\xF6jer.",html:()=>`${i}
        <h2>Leveranss\xE4tt och pris</h2>
        <p>Vi levererar till adresser i Sverige. ${u} Du ser alltid leveranss\xE4tt, fraktkostnad och totalsumma i kassan innan du betalar.</p>
        <h2>Leveranstid</h2>
        <p>${g} Varje produktsida visar vilka datum paketet ber\xE4knas komma${s.cutoffHour?`, och best\xE4llningar f\xF6re klockan ${s.cutoffHour} p\xE5 vardagar r\xE4knas fr\xE5n samma dag`:""}.</p>
        <h2>Flera paket</h2>
        <p>Varor fr\xE5n olika leverant\xF6rer kan komma i separata paket. Om det inneb\xE4r en extra kostnad ser du det innan du betalar.</p>
        <h2>Om leveransen dr\xF6jer eller inte kommer</h2>
        <p>H\xF6r av dig till oss om den \xF6verenskomna leveranstiden har passerat. Om ingen tid avtalades ska varan normalt levereras inom 30 dagar. Du kan kr\xE4va leverans, h\xE5lla inne betalning som inte \xE4r gjord och, n\xE4r villkoren i lagen \xE4r uppfyllda, h\xE4va k\xF6pet och beg\xE4ra ers\xE4ttning.</p>
        <p>Skriv till ${e} med ordernummer och en kort beskrivning. Skicka aldrig l\xF6senord eller fullst\xE4ndiga kortuppgifter via e-post.</p>
        <h2>Sp\xE5rning</h2>
        <p>Anv\xE4nd l\xE4nken till orderstatus i orderbekr\xE4ftelsen. Sp\xE5rning fr\xE5n fraktbolaget visas n\xE4r leverant\xF6ren eller fraktbolaget skickar den. Du kan ocks\xE5 anv\xE4nda <a href="#spara-order">Sp\xE5ra min best\xE4llning</a>.</p>
        <h2>Tull och avgifter</h2>
        <p>M\xE5let \xE4r att allt skickas fr\xE5n lager inom EU, och d\xE5 tillkommer ingen tull eller importavgift. Priset du ser \xE4r inklusive moms.</p>
        <h2>V\xE5rt ansvar</h2>
        <p>RumIQ \xE4r din kontakt f\xF6r leverans, \xE5nger och reklamation, \xE4ven n\xE4r en leverant\xF6r skickar varan. Leverant\xF6rens villkor kan aldrig begr\xE4nsa dina r\xE4ttigheter som konsument.</p>
        <h2>Att bekr\xE4fta f\xF6re f\xF6rs\xE4ljning</h2>
        <ul class="checklist"><li>Leverant\xF6rernas leveransregler och lagerplats</li><li>L\xE4nder vi s\xE4ljer till</li><li>Fraktpriser och gr\xE4nsen f\xF6r fri frakt</li></ul>`},returer:{title:"Returer & \xE5terbetalning",kicker:"Kundservice",lead:"\xC5ngrat dig eller blivit n\xE5got fel? S\xE5 h\xE4r g\xF6r du.",html:()=>`${i}
        <h2>${a.openDays?`${a.openDays} dagars \xF6ppet k\xF6p`:"\xC5ngerr\xE4tt"}</h2>
        <p>${m} Du beh\xF6ver inte ange n\xE5got sk\xE4l. Det enklaste s\xE4ttet att \xE5ngra \xE4r <a href="#angra">\xC5ngra avtalet h\xE4r</a>, som finns i sidfoten och under varje best\xE4llning i ditt konto.</p>
        <h2>S\xE5 skickar du tillbaka</h2>
        <ol><li>\xC5ngra k\xF6pet via knappen. Du f\xE5r en bekr\xE4ftelse direkt.</li><li>Packa varan v\xE4l, g\xE4rna i originalf\xF6rpackningen.</li><li>Skicka varan inom 14 dagar fr\xE5n att du \xE5ngrade k\xF6pet. Returadressen st\xE5r i bekr\xE4ftelsen.</li></ol>
        <h2>\xC5terbetalning</h2>
        <p>Vi betalar tillbaka utan on\xF6digt dr\xF6jsm\xE5l och senast 14 dagar fr\xE5n ditt meddelande om att du \xE5ngrar k\xF6pet, inklusive den ursprungliga fraktkostnaden f\xF6r standardleverans. Vi f\xE5r v\xE4nta tills vi f\xE5tt tillbaka varan eller bevis p\xE5 att den skickats. Pengarna kommer tillbaka p\xE5 samma s\xE4tt som du betalade, om vi inte kommer \xF6verens om n\xE5got annat utan kostnad f\xF6r dig.</p>
        <h2>Returfrakt</h2>
        <p>Returen skickas till en adress i Sverige, inte till leverant\xF6ren utomlands. ${l("Vem som betalar returfrakten")}</p>
        ${(()=>{const r=((window.RQ_CONFIG||{}).delivery||{}).returnVia||[];return r.length?`<p>Du l\xE4mnar returen ${r.length>1?r.slice(0,-1).join(", ")+" eller "+r[r.length-1]:r[0]}. Du f\xE5r en returetikett i bekr\xE4ftelsen n\xE4r du har \xE5ngrat k\xF6pet.</p>`:""})()}
        <h2>Varans skick</h2>
        <p>Du f\xE5r unders\xF6ka varan p\xE5 samma s\xE4tt som i en butik. Om varan har hanterats mer \xE4n s\xE5 kan vi g\xF6ra avdrag f\xF6r v\xE4rdeminskningen.</p>
        <h2>Fel p\xE5 varan</h2>
        <p>\xC4r n\xE5got trasigt eller fel? L\xE4s om <a href="#juridik-garanti">reklamation och garanti</a>.</p>`},betalning:{title:"Betalning",kicker:"Kundservice",lead:"Betalning och slutlig totalsumma hanteras i Shopifys kassa.",html:()=>`
        <h2>Betals\xE4tt</h2>
        <p>De betals\xE4tt som g\xE5r att anv\xE4nda \xE4r de som visas i kassan. Vilka kort, fakturor och pl\xE5nb\xF6cker som finns beror p\xE5 butikens inst\xE4llningar och var du handlar ifr\xE5n.</p>
        <h2>Priser och moms</h2>
        <p>Priserna anges i svenska kronor. Moms, andra skatter och fraktkostnad visas innan du betalar, och den slutliga summan ser du i kassan.</p>
        <h2>S\xE4ker betalning</h2>
        <p>Betalningen sker i Shopifys kassa, inte i ett kortformul\xE4r p\xE5 den h\xE4r sajten. Shopify och betalleverant\xF6ren hanterar kortuppgifterna. Vi samlar aldrig in fullst\xE4ndiga kortnummer eller s\xE4kerhetskoder. Inget system kan garantera fullst\xE4ndig s\xE4kerhet, men kortdata hanteras enligt branschens regler.</p>
        <h2>\xC5terbetalning</h2>
        <p>Vid \xE5nger betalar vi tillbaka utan on\xF6digt dr\xF6jsm\xE5l och senast 14 dagar fr\xE5n ditt meddelande. F\xF6r varor f\xE5r vi v\xE4nta tills vi har f\xE5tt tillbaka varan eller bevis p\xE5 att den skickats. \xC5terbetalningen g\xF6rs med samma betals\xE4tt, om vi inte kommer \xF6verens om n\xE5got annat utan kostnad f\xF6r dig.</p>`},kontakt:{title:"Kontakt",kicker:"Kundservice",lead:"Vi l\xE4ser varje meddelande och svarar s\xE5 snart vi kan.",html:()=>`<div class="contact">
        <form id="contactForm" class="form-grid" novalidate>
          <label>Namn<input name="name" autocomplete="name" required></label>
          <label>E-post<input name="email" type="email" autocomplete="email" required></label>
          <label>Ordernummer, om du har ett<input name="order" placeholder="Till exempel TEST-1001"></label>
          <label>Vad g\xE4ller det?<select name="topic"><option>En best\xE4llning</option><option>En produkt</option><option>Retur eller reklamation</option><option>Mitt rum och verktygen</option><option>N\xE5got annat</option></select></label>
          <label class="full">Meddelande<textarea name="msg" rows="6" required></textarea></label>
          <p class="note full">Skicka aldrig l\xF6senord eller fullst\xE4ndiga kortuppgifter.</p>
          <button class="btn" type="submit">Skicka meddelandet</button>
          <p class="status full" role="status" id="contactStatus"></p>
        </form>
        <aside class="contact-side">
          <h3>Snabbast hj\xE4lp</h3>
          <p><a href="#faq">Vanliga fr\xE5gor</a><br><a href="#spara-order">Sp\xE5ra min best\xE4llning</a><br><a href="#angra">\xC5ngra avtalet h\xE4r</a><br><a href="#returer">Returer & \xE5terbetalning</a></p>
          <h3>E-post</h3><p>${e}</p>
          <h3>F\xF6retaget</h3><p class="small">${d()}</p>
        </aside></div>`},faq:{title:"Vanliga fr\xE5gor",kicker:"Kundservice",lead:"Svar p\xE5 det folk oftast undrar. Hittar du inte ditt svar, skriv till oss.",groups:[["Best\xE4llningar",[["Hur fungerar RumIQ?","Du hittar produkter i butiken eller med hj\xE4lp av Svep och Hitta r\xE4tt, ser dem i ditt rum om du vill och betalar i en s\xE4ker kassa. L\xE4s mer under <a href='#sa-fungerar-det'>S\xE5 fungerar RumIQ</a>."],["Hur g\xF6r jag en best\xE4llning?","L\xE4gg produkterna i varukorgen, \xF6ppna varukorgen och g\xE5 till kassan. D\xE4r v\xE4ljer du leveranss\xE4tt och ser totalsumman innan du betalar."],["Kan jag \xE4ndra min best\xE4llning?","H\xF6r av dig s\xE5 snart som m\xF6jligt med ditt ordernummer. Har best\xE4llningen inte skickats \xE4ndrar vi den om det g\xE5r."],["Kan jag avbryta min best\xE4llning?","Ja. Skriv till oss innan den har skickats. Har den redan skickats kan du anv\xE4nda din \xE5ngerr\xE4tt i st\xE4llet."]]],["Leverans",[["Hur l\xE5ng tid tar leveransen?",`${g} De datum paketet ber\xE4knas komma visas p\xE5 varje produktsida och i kassan innan du betalar.`],["Vad kostar frakten?",`${u} Du ser fraktkostnaden i kassan innan du betalar.`],["Hur sp\xE5rar jag mitt paket?","Anv\xE4nd l\xE4nken i orderbekr\xE4ftelsen eller <a href='#spara-order'>Sp\xE5ra min best\xE4llning</a>."],["Vad g\xF6r jag om leveransen \xE4r f\xF6rsenad?","H\xF6r av dig med ditt ordernummer. Om ingen leveranstid avtalades ska varan normalt komma inom 30 dagar, och du har r\xE4ttigheter enligt lag om den dr\xF6jer."]]],["Betalning",[["Vilka betalningsmetoder accepterar ni?","De som visas i kassan. Vilka det \xE4r beror p\xE5 butikens inst\xE4llningar och var du handlar ifr\xE5n."],["\xC4r min betalning s\xE4ker?","Betalningen sker i Shopifys kassa. Vi ser eller sparar aldrig dina fullst\xE4ndiga kortuppgifter."],["Var hittar jag mitt kvitto?","Kvittot kommer i orderbekr\xE4ftelsen via e-post. \xC4r du inloggad ser du dina best\xE4llningar under Mitt konto."]]],["Returer",[["Hur \xE5ngrar jag ett k\xF6p?","Anv\xE4nd <a href='#angra'>\xC5ngra avtalet h\xE4r</a>. Du beh\xF6ver inte logga in och inte ange n\xE5got sk\xE4l."],["Hur returnerar jag en produkt?","\xC5ngra k\xF6pet f\xF6rst. Packa sedan varan v\xE4l och skicka den till returadressen i bekr\xE4ftelsen inom 14 dagar."],["Hur l\xE5ng \xE4r \xE5ngerfristen?",m],["Hur fungerar \xE5terbetalningar?","Vi betalar tillbaka senast 14 dagar fr\xE5n att du \xE5ngrade k\xF6pet, med samma betals\xE4tt. Vi f\xE5r v\xE4nta tills varan har kommit tillbaka eller du visat att den skickats."]]],["Produkter",[["Omfattas produkterna av garanti?","Du har alltid r\xE4tt att reklamera fel i tre \xE5r enligt konsumentk\xF6plagen. Om en tillverkare ger en garanti ut\xF6ver det st\xE5r det p\xE5 produktsidan."],["Hur v\xE4ljer jag r\xE4tt produkt?","L\xE4s produktsidan, prova produkten i Mitt rum eller fr\xE5ga stylisten."],["Vad g\xF6r jag om produkten \xE4r felaktig?","Skriv till oss med ordernummer och g\xE4rna en bild, s\xE5 l\xF6ser vi det. L\xE4s mer om <a href='#juridik-garanti'>reklamation</a>."],["Varf\xF6r kan jag inte k\xF6pa vissa produkter?","RumIQ \xE4r i en tidig fas. Produkter m\xE4rkta Exempel visar hur butiken kommer att se ut men g\xE5r inte att k\xF6pa \xE4n."]]],["Mitt rum och verktygen",[["Vad kostar verktygen?","Ingenting. Mitt rum, Svep, Hitta r\xE4tt och stylisten \xE4r gratis. Studio Plus \xE4r ett tillval f\xF6r dig som vill ha fler AI-bilder."],["Hur m\xE5nga rumsbilder kan jag skapa?","Hur m\xE5nga du vill n\xE4r du sj\xE4lv st\xE4ller in produkterna i ditt foto. Det sker direkt i webbl\xE4saren. AI-bilder \xE4r n\xE5got annat: med ett konto f\xE5r du 5 i m\xE5naden utan kostnad, och fler med Studio Plus."],["R\xE4knas det om en bild misslyckas?","Nej. F\xF6rs\xF6k som inte ger n\xE5got resultat r\xE4knas aldrig."],["\xC4r AI-bilderna exakta?","Nej. Bilderna \xE4r illustrationer och storlek, f\xE4rg och detaljer kan skilja sig fr\xE5n den riktiga produkten. Kontrollera produktsidan innan du k\xF6per."],["Vad h\xE4nder med mitt foto?","Fotot stannar i din webbl\xE4sare s\xE5 l\xE4nge du sj\xE4lv st\xE4ller in produkterna. V\xE4ljer du att skapa en AI-bild skickas fotot till en server f\xF6r att bilden ska kunna skapas, f\xF6rst efter att du har godk\xE4nt det, och rumsfotot raderas d\xE4r efter 30 dagar."],["\xC4r bilderna p\xE5 sajten riktiga foton?","Nej. Bilderna p\xE5 produkter och rum \xE4r skapade med AI medan vi v\xE4ntar p\xE5 de f\xF6rsta produkterna. N\xE4r produkterna finns byter vi till riktiga foton."]]]],html(){return this.groups.map(([r,k],h)=>`<section class="faq-group" id="faq-${h}"><h2>${r}</h2>${k.map(([v,f])=>`<details><summary>${v}<span class="pm" aria-hidden="true"></span></summary><div class="ans"><p>${f}</p></div></details>`).join("")}</section>`).join("")+'<div class="faq-more"><h3>Beh\xF6ver du mer hj\xE4lp?</h3><a class="btn ghost" href="#kontakt">Kontakta oss</a></div>'}},om:{title:"Om RumIQ",kicker:"V\xE5r ber\xE4ttelse",lead:"Ett b\xE4ttre hem kr\xE4ver inte fler saker. Det kr\xE4ver r\xE4tt saker.",html:()=>`
        <p class="big">RumIQ \xE4r en skandinavisk webbutik f\xF6r hemmet. Ett noga utvalt sortiment, inspiration f\xF6r varje rum och verktyg som l\xE5ter dig se produkterna hemma hos dig innan du k\xF6per.</p>
        <h2>Vad RumIQ \xE4r</h2>
        <p>Vi s\xE4ljer belysning, textil, f\xF6rvaring, saker f\xF6r k\xF6k och badrum och smarta saker f\xF6r vardagen. Kvaliteten ska k\xE4nnas premium, priset ska k\xE4nnas rimligt. Till det kommer ett magasin med id\xE9er och verktyg som hj\xE4lper dig att v\xE4lja: Mitt rum, Svep och Hitta r\xE4tt.</p>
        <h2>Det h\xE4r vill vi g\xF6ra</h2>
        <h3>V\xE4lja r\xE4tt, inte mer</h3>
        <p>Vi vill hj\xE4lpa dig att v\xE4lja f\xE4rre och b\xE4ttre saker. Varje produkt ska fylla en funktion i ett verkligt hem, h\xE5lla l\xE4nge och fungera ihop med resten.</p>
        <h3>Mindre gissande f\xF6re k\xF6pet</h3>
        <p>I Mitt rum ser du produkterna i ditt eget rum innan du k\xF6per. M\xE5let \xE4r f\xE4rre felk\xF6p, f\xF6r en retur \xE4r det s\xE4msta f\xF6r b\xE5de pl\xE5nboken och milj\xF6n.</p>
        <h3>\xC4rligt hela v\xE4gen</h3>
        <p>AI-bilder m\xE4rks som inspiration. Pris och frakt visas innan du betalar. Vi hittar inte p\xE5 recensioner, lagersaldon eller leveransl\xF6ften.</p>
        <h2>S\xE5 vill vi f\xF6rb\xE4ttra hela upplevelsen</h2>
        <p>Fr\xE5n att du uppt\xE4cker n\xE5got, till att du ser det i ditt rum, sparar det och best\xE4ller i n\xE5gra f\xE5 steg. Utan att du beh\xF6ver gissa.</p>
        <h2>D\xE4r vi \xE4r i dag</h2>
        <p>RumIQ \xE4r i en tidig fas. Sortimentet v\xE4xer och vissa produkter \xE4r tydligt m\xE4rkta exempel som inte g\xE5r att k\xF6pa \xE4n. Vi har inget eget lager. Tanken \xE4r att leverant\xF6rerna skickar direkt till dig fr\xE5n lager inom EU, och leverant\xF6rerna bekr\xE4ftas innan butiken \xF6ppnar.</p>
        <h2>Fr\xE5gor eller id\xE9er?</h2>
        <p>Skriv till ${e} eller <a href="#onska">\xF6nska n\xE5got</a>. Vi l\xE4ser allt.</p>`}},t.LEGAL={villkor:{title:"K\xF6pvillkor",lead:"Villkoren som g\xE4ller n\xE4r du handlar hos RumIQ.",html:()=>`${i}
      <h2>1. S\xE4ljare</h2><p>${d()}. E-post ${e}.</p>
      <h2>2. Priser</h2><p>Priserna anges i svenska kronor inklusive moms. Fraktkostnad och eventuella avgifter visas i kassan innan du betalar.</p>
      <h2>3. Best\xE4llning och avtal</h2><p>Avtalet ing\xE5s n\xE4r du f\xE5r en orderbekr\xE4ftelse via e-post. Vid uppenbart felaktiga priser eller om en vara inte kan levereras har vi r\xE4tt att h\xE4va k\xF6pet, och betalar d\xE5 tillbaka hela beloppet.</p>
      <h2>4. Betalning</h2><p>Betalningen hanteras i Shopifys kassa. Se <a href="#betalning">Betalning</a>.</p>
      <h2>5. Leverans</h2><p>Se <a href="#frakt">Frakt & leverans</a>. Blir en leverans v\xE4sentligt f\xF6rsenad har du r\xE4tt att h\xE4va k\xF6pet.</p>
      <h2>6. \xC5ngerr\xE4tt</h2><p>Du har 14 dagars \xE5ngerr\xE4tt enligt lagen om distansavtal.${a.openDays?` Hos oss har du dessutom ${a.openDays} dagars \xF6ppet k\xF6p fr\xE5n att du tog emot varan.`:""} Se <a href="#juridik-angerratt">\xC5ngerr\xE4tt</a> och <a href="#angra">\xC5ngra avtalet h\xE4r</a>.</p>
      <h2>7. Reklamation</h2><p>Du har r\xE4tt att reklamera fel i tre \xE5r enligt konsumentk\xF6plagen. Se <a href="#juridik-garanti">Reklamation & garanti</a>.</p>
      <h2>8. Personuppgifter</h2><p>Se <a href="#juridik-integritet">Integritetspolicy</a>.</p>
      <h2>9. Tvister</h2><p>Vi f\xF6ljer Allm\xE4nna reklamationsn\xE4mndens (ARN) rekommendationer. Du kan ocks\xE5 anv\xE4nda EU:s plattform f\xF6r tvistl\xF6sning online.</p>`},integritet:{title:"Integritetspolicy",lead:"Vilka uppgifter vi behandlar, varf\xF6r och hur l\xE4nge.",html:()=>`${i}
      <h2>Personuppgiftsansvarig</h2><p>${d()}. Fr\xE5gor om personuppgifter: ${e}.</p>
      <h2>Vad vi behandlar</h2><ul>
        <li><b>Best\xE4llningar:</b> namn, adress, e-post och telefon f\xF6r att leverera och f\xF6r bokf\xF6ring. Sparas i sju \xE5r enligt bokf\xF6ringslagen.</li>
        <li><b>Konto:</b> e-post, favoriter, sparade rum och stilprofil, s\xE5 l\xE4nge du har kvar kontot.</li>
        <li><b>Mitt rum:</b> foton av ditt rum stannar i din webbl\xE4sare. F\xF6rst n\xE4r du sj\xE4lv v\xE4ljer att skapa en AI-bild, och har godk\xE4nt det, skickas fotot f\xF6r att skapa bilden. Se avsnittet om AI-bilder nedan.</li>
        <li><b>Kundservice:</b> det du skriver till oss, s\xE5 l\xE4nge \xE4rendet p\xE5g\xE5r och d\xE4refter h\xF6gst tv\xE5 \xE5r.</li>
        <li><b>V\xE4ntelista och nyhetsbrev:</b> e-post, med ditt samtycke, tills du avregistrerar dig.</li></ul>
      <h2>Mottagare</h2><p>E-handelsplattform, betal- och fraktpartner samt leverant\xF6rer som skickar din best\xE4llning. ${l("Fullst\xE4ndig lista \xF6ver personuppgiftsbitr\xE4den")}</p>
      <h2>Dina r\xE4ttigheter</h2><p>Du kan beg\xE4ra utdrag, r\xE4ttelse och radering, inv\xE4nda mot behandling och f\xE5 dina uppgifter flyttade. Skriv till ${e}. Du kan ocks\xE5 klaga hos Integritetsskyddsmyndigheten (IMY).</p>`},cookies:{title:"Cookiepolicy",lead:"Vi anv\xE4nder bara n\xF6dv\xE4ndiga cookies om du inte v\xE4ljer n\xE5got annat.",html:()=>`
      <h2>N\xF6dv\xE4ndiga</h2><p>Varukorg, inloggning, spr\xE5k och dina cookieval. Kr\xE4vs f\xF6r att butiken ska fungera och kan inte st\xE4ngas av.</p>
      <h2>Statistik</h2><p>Hj\xE4lper oss att f\xF6rst\xE5 vilka sidor som anv\xE4nds. Bara med ditt samtycke.</p>
      <h2>Marknadsf\xF6ring</h2><p>G\xF6r annonser mer relevanta. Bara med ditt samtycke.</p>
      <h2>Lagring i webbl\xE4saren</h2><p>Varukorg, det du sparat och din stilprofil sparas i din webbl\xE4sares lokala lagring i den h\xE4r versionen. Du kan rensa allt under Mitt konto.</p>
      <p><button class="btn ghost" type="button" data-action="cookies">\xC4ndra mina cookieval</button></p>`},angerratt:{title:"\xC5ngerr\xE4tt",lead:"Din r\xE4tt att \xE5ngra ett k\xF6p p\xE5 n\xE4tet.",html:()=>`${i}
      <p>Enligt lagen om distansavtal har du r\xE4tt att \xE5ngra k\xF6pet inom 14 dagar fr\xE5n den dag du, eller n\xE5gon du utsett, tog emot varan. Vid flera varor i samma best\xE4llning r\xE4knas fristen fr\xE5n dagen du fick den sista.</p>${a.openDays?`
      <p>Hos oss har du dessutom ${a.openDays} dagars \xF6ppet k\xF6p fr\xE5n att du tog emot varan.</p>`:""}
      <h2>S\xE5 \xE5ngrar du</h2><p>Anv\xE4nd <a href="#angra">\xC5ngra avtalet h\xE4r</a> eller skicka ett tydligt meddelande till ${e}. Du kan ocks\xE5 anv\xE4nda Konsumentverkets standardformul\xE4r f\xF6r \xE5nger.</p>
      <h2>Undantag</h2><p>\xC5ngerr\xE4tten g\xE4ller inte bland annat varor som tillverkats efter dina specifikationer, f\xF6rseglade hygienvaror som brutits efter leverans och varor som snabbt kan f\xF6rs\xE4mras.</p>
      <h2>\xC5terbetalning</h2><p>Se <a href="#returer">Returer & \xE5terbetalning</a>.</p>`},garanti:{title:"Reklamation & garanti",lead:"Om n\xE5got \xE4r fel p\xE5 varan.",html:()=>`${i}
      <h2>Reklamationsr\xE4tt</h2><p>Du har r\xE4tt att reklamera ursprungliga fel i tre \xE5r fr\xE5n att du tog emot varan, enligt konsumentk\xF6plagen. Fel som visar sig inom tv\xE5 \xE5r antas ha funnits fr\xE5n b\xF6rjan, om inte vi kan visa n\xE5got annat.</p>
      <h2>S\xE5 reklamerar du</h2><p>Skriv till ${e} inom sk\xE4lig tid efter att du uppt\xE4ckt felet. Tv\xE5 m\xE5nader r\xE4knas alltid som sk\xE4lig tid. Ange ordernummer, vad som \xE4r fel och bifoga g\xE4rna en bild.</p>
      <h2>Vad som h\xE4nder sedan</h2><p>Vi r\xE4ttar felet, byter varan, s\xE4nker priset eller betalar tillbaka, beroende p\xE5 felet och vad du vill. Vi st\xE5r f\xF6r kostnaden f\xF6r att skicka tillbaka en felaktig vara.</p>
      <h2>Garanti</h2><p>En garanti fr\xE5n tillverkaren \xE4r ett till\xE4gg och begr\xE4nsar aldrig din reklamationsr\xE4tt. Om en produkt har garanti st\xE5r det p\xE5 produktsidan.</p>`},produktsakerhet:{title:"Produkts\xE4kerhet",lead:"Hur vi arbetar f\xF6r att produkterna ska vara s\xE4kra.",html:()=>`${i}
      <p>Produkterna vi s\xE4ljer ska uppfylla EU:s krav p\xE5 produkts\xE4kerhet, inklusive f\xF6rordningen om allm\xE4n produkts\xE4kerhet (GPSR).</p>
      <h2>M\xE4rkning och information</h2><p>Varje produkt ska ha tillverkare eller ansvarig person inom EU angiven, tillsammans med de s\xE4kerhets- och bruksanvisningar som beh\xF6vs. Uppgifterna visas p\xE5 produktsidan n\xE4r produkten \xE4r verifierad.</p>
      <h2>Elektriska produkter</h2><p>Lampor och laddare ska vara CE-m\xE4rkta och f\xF6lja reglerna f\xF6r els\xE4kerhet. Anv\xE4nd dem enligt bruksanvisningen.</p>
      <h2>\xC5terkallelser</h2><p>Om en produkt \xE5terkallas meddelar vi alla som k\xF6pt den och visar informationen h\xE4r.</p>
      <h2>Rapportera ett problem</h2><p>Har en produkt skadat n\xE5gon eller kan vara farlig? Sluta anv\xE4nda den och skriv till ${e} direkt.</p>`},sakerhet:{title:"S\xE4kerhet",lead:"Hur vi skyddar din information.",html:()=>`
      <h2>Betalningar</h2><p>Betalningar sker i Shopifys kassa. Vi ser eller sparar aldrig fullst\xE4ndiga kortnummer eller s\xE4kerhetskoder.</p>
      <h2>Ditt konto</h2><p>Anv\xE4nd ett unikt l\xF6senord. Vi fr\xE5gar aldrig efter ditt l\xF6senord via e-post eller telefon.</p>
      <h2>Bedr\xE4gerier</h2><p>F\xE5r du ett meddelande som p\xE5st\xE5r sig komma fr\xE5n RumIQ och ber om kortuppgifter eller l\xF6senord, svara inte. Skicka det g\xE4rna vidare till ${e}.</p>
      <h2>Rapportera en s\xE4kerhetsbrist</h2><p>Har du hittat en s\xE4kerhetsbrist p\xE5 sajten? Skriv till ${e} med en beskrivning. Vi tackar alla som rapporterar i god tro.</p>`},foretag:{title:"F\xF6retagsinformation",lead:"Vem som s\xE4ljer och hur du n\xE5r oss.",html:()=>`
      <h2>Varum\xE4rke och kundservice</h2><p>Varum\xE4rke: RumIQ. Kundservice och integritetsfr\xE5gor: ${e}.</p>
      <h2>S\xE4ljare</h2><p>${d()}</p>
      <p>Momsregistreringsnummer: ${n.vat||l("momsnummer")}</p>
      <p>Returadress: ${n.returnAddress||l("verifierad returadress")}</p>
      <p class="note">Supportadressen ers\xE4tter inte de obligatoriska uppgifterna om s\xE4ljaren. De kompletteras innan f\xF6rs\xE4ljningen b\xF6rjar.</p>`}},t.ARTICLES=[{slug:"vardagsdukning",img:"assets/img/mag/vardagsdukning-1200.webp",minutes:3,rooms:["kok"],title:"En v\xE4lkomnande dukning, \xE4ven en vanlig tisdag",lead:"Ge plats \xE5t vardagens m\xE5ltider med en dukning som \xE4r l\xE4tt att anv\xE4nda och lika l\xE4tt att plocka undan.",body:`<p>Det dukade bordet f\xF6rknippas med helger och g\xE4ster. Men det \xE4r vardagens m\xE5ltider som blir flest, och de f\xF6rtj\xE4nar ocks\xE5 lite omsorg. Tricket \xE4r att v\xE4lja saker som g\xF6r det enklare, inte mer arbete.</p>
        <h2>B\xF6rja med det som redan st\xE5r framme</h2><p>En sk\xE4rbr\xE4da i tr\xE4 kan vara b\xE5de arbetsyta och serveringsfat. L\xE4gg br\xF6det direkt p\xE5 den, st\xE4ll sm\xF6ret bredvid och b\xE4r in allt p\xE5 en g\xE5ng. En sak mindre att diska, och bordet ser genast mer genomt\xE4nkt ut.</p>
        <h2>En sak p\xE5 h\xF6jden</h2><p>Ett bord blir levande n\xE4r n\xE5got bryter den platta ytan. En vas med n\xE5gra kvistar eller en liten lampa r\xE4cker. H\xE5ll det l\xE5gt nog att man ser varandra.</p>
        <h2>Textil som t\xE5l vardag</h2><p>Linne och bomull blir finare ju mer de anv\xE4nds. V\xE4lj handdukar och servetter som g\xE5r att tv\xE4tta varmt och som inte beh\xF6ver strykas.</p>
        <h2>L\xE4tt att plocka undan</h2><p>Det b\xE4sta vardagsbordet \xE4r dukat p\xE5 en minut och avdukat p\xE5 tv\xE5. Ha en korg eller bricka f\xF6r det som ska tillbaka till k\xF6ket, s\xE5 blir det en vana och inte ett projekt.</p>`,picks:["skarbrada-ek-med-handtag","sand-keramikvas","svamp-uppladdningsbar-lampa"]},{slug:"farger-att-trivas-med",img:"assets/img/mag/farger-1200.webp",minutes:4,rooms:["vardagsrum","sovrum"],title:"Skapa en f\xE4rgpalett att trivas med",lead:"Kombinera v\xE4lbekanta f\xE4rger, lite kontrast och det ljus du faktiskt har.",body:`<p>En f\xE4rgpalett f\xF6r hemmet beh\xF6ver inte b\xF6rja med ett f\xE4rgkort. Den kan b\xF6rja med det du redan tycker om: tr\xF6jan du alltid tar p\xE5 dig, tallriken du alltid v\xE4ljer, ljuset en eftermiddag i september.</p>
        <h2>En bas, en v\xE4rme, en kontrast</h2><p>T\xE4nk i tre lager. En lugn bas f\xF6r v\xE4ggar och stora ytor, ofta ljus kalk eller havre. En v\xE4rme fr\xE5n tr\xE4, terrakotta eller ull. Och en kontrast, n\xE5got m\xF6rkare som f\xE5r resten att vila: grafit, en djup gr\xF6n eller svart metall.</p>
        <h2>Ljuset best\xE4mmer</h2><p>Samma vita v\xE4gg ser bl\xE5 ut i norrljus och gul i kv\xE4llslampans sken. Titta p\xE5 f\xE4rgprover vid olika tider p\xE5 dygnet innan du best\xE4mmer dig. Varmt ljus fr\xE5n lampor med opal- eller textilsk\xE4rm g\xF6r det mesta mjukare.</p>
        <h2>Upprepa, men inte exakt</h2><p>En f\xE4rg som \xE5terkommer i tv\xE5 eller tre rum binder ihop hemmet. L\xE5t den komma tillbaka i olika material: en kudde i ett rum, en kruka i ett annat.</p>
        <p>Vill du veta vilka f\xE4rger ditt rum redan har? <a href="#mitt-rum">Mitt rum</a> plockar ut paletten ur ditt foto och visar vad som passar.</p>`,picks:["plad-ullblandning-havre","terrakottakruka-rafflad","lysa-keramiklampa"]},{slug:"texturer-och-material",img:"assets/img/mag/texturer-1200.webp",minutes:3,rooms:["vardagsrum","badrum"],title:"Texturer och material: ge ett enkelt rum personlighet",lead:"Sl\xE4ta, v\xE4vda och mjuka ytor g\xF6r ett rum varmare utan att du beh\xF6ver byta ut allt du har.",body:`<p>Ett rum d\xE4r allt \xE4r sl\xE4tt och blankt k\xE4nns ofta kallt, \xE4ven om f\xE4rgerna \xE4r varma. Det \xE4r texturerna som g\xF6r skillnaden, och de \xE4r l\xE4tta att l\xE4gga till.</p>
        <h2>Tre ytor per rum</h2><p>F\xF6rs\xF6k ha minst tre olika ytor i varje rum: n\xE5got sl\xE4tt, som glas eller lackat tr\xE4, n\xE5got v\xE4vt, som en korg eller ett linnetyg, och n\xE5got mjukt, som ull eller filt.</p>
        <h2>L\xE5t materialen \xE5ldras</h2><p>Ek, keramik och linne blir vackrare med \xE5ren. De t\xE5l m\xE4rken och f\xE5r patina i st\xE4llet f\xF6r att se slitna ut. En bra tumregel f\xF6r saker du anv\xE4nder varje dag.</p>
        <h2>B\xF6rja i det lilla</h2><p>En fl\xE4tad korg f\xF6r filtarna, burkar med lock i tr\xE4, ett kuddfodral i linne. Sm\xE5 saker, men tillsammans \xE4ndrar de hur rummet k\xE4nns.</p>`,picks:["flatad-forvaringskorg","forradsburkar-glas-ek-3-pack","lin-kuddfodral"]},{slug:"fran-garderob-till-hem",img:"assets/img/mag/garderob-1200.webp",minutes:3,rooms:["sovrum"],title:"Fr\xE5n garderob till hem: hitta din personliga stil",lead:"F\xE4rgerna, texturerna och kontrasterna du gillar att b\xE4ra kan bli utg\xE5ngspunkten f\xF6r ett hem som k\xE4nns som du.",body:`<p>De flesta har en tydligare stil i garderoben \xE4n i vardagsrummet. Det \xE4r inte konstigt: kl\xE4der v\xE4ljer vi varje dag, m\xF6bler n\xE5gra g\xE5nger i livet. Men smaken \xE4r densamma, och den g\xE5r att l\xE5na.</p>
        <h2>\xD6ppna garderoben</h2><p>Vilka f\xE4rger dominerar? Vilka material tar du helst p\xE5 dig: stickat, linne, denim? \xC4r du mer f\xF6r det rena och enkla eller det mjuka och lagrade? Svaren \xE4r en bra start f\xF6r hemmet ocks\xE5.</p>
        <h2>\xD6vers\xE4tt materialen</h2><p>\xC4lskar du ullkoftor blir en pl\xE4d i ullblandning ett naturligt val. Gillar du linneskjortor passar kuddfodral i linne. Den som b\xE4r mycket grafit trivs ofta med m\xF6rka detaljer, som en tv\xE5lpump i m\xF6rkt stengods eller en grafisk affisch.</p>
        <h2>G\xF6r testet</h2><p>Vill du ha hj\xE4lp att s\xE4tta ord p\xE5 stilen? <a href="#svep">Svep fram din stil</a> tar en minut och ger f\xF6rslag ur sortimentet.</p>`,picks:["plad-ullblandning-havre","vila-paslakanset-linne","glob-bordslampa-opalglas"]},{slug:"harmoniskt-hem",img:"assets/img/mag/harmoniskt-1200.webp",minutes:5,rooms:["vardagsrum","hall","sovrum"],title:"7 s\xE4tt att skapa ett mer harmoniskt hem",lead:"Ett lugnare hem b\xF6rjar med hur du anv\xE4nder det, inte med hur mycket du k\xF6per.",body:`<ol class="numbered">
        <li><h3>Ge varje sak en adress</h3><p>Det som saknar en fast plats blir liggande. Best\xE4m var nycklarna, laddaren och fj\xE4rrkontrollen bor.</p></li>
        <li><h3>L\xE4gre ljus p\xE5 kv\xE4llen</h3><p>Sl\xE4ck taklampan och t\xE4nd tv\xE5 eller tre lampor p\xE5 l\xE4gre h\xF6jd. Rummet blir lugnare direkt.</p></li>
        <li><h3>D\xF6lj det som surrar</h3><p>Sladdar och laddare syns mer \xE4n man tror. En l\xE5da med lock g\xF6r stor skillnad f\xF6r liten insats.</p></li>
        <li><h3>L\xE5t ytorna andas</h3><p>En tom b\xE4nk eller hylla \xE4r inte oanv\xE4nd. Den ger blicken vila.</p></li>
        <li><h3>Samla sm\xE5saker i korgar</h3><p>Tio saker i en korg ser ut som en sak. Tio saker utspridda ser ut som tio.</p></li>
        <li><h3>Upprepa material</h3><p>Samma tr\xE4, samma metall eller samma textil i flera rum g\xF6r att hemmet h\xE4nger ihop.</p></li>
        <li><h3>Byt hellre \xE4n l\xE4gg till</h3><p>N\xE4r n\xE5got nytt kommer in, fundera p\xE5 vad som kan f\xE5 g\xE5. Det h\xE5ller hemmet l\xE4tt.</p></li></ol>`,picks:["forvaringslada-filt","flatad-forvaringskorg","glod-doftljus-keramik"]},{slug:"skandinavisk-inspiration",img:"assets/img/mag/skandinavisk-1200.webp",minutes:4,rooms:["vardagsrum","kok"],title:"Skandinavisk inredningsinspiration",lead:"Naturligt ljus, genomt\xE4nkta proportioner och enkla vardagsrutiner.",body:`<p>Skandinavisk inredning handlar mindre om en stil och mer om ett s\xE4tt att leva med m\xF6rka vintrar och ljusa somrar. Ljuset \xE4r det dyrbaraste vi har, och allt annat anpassar sig efter det.</p>
        <h2>Ta vara p\xE5 dagsljuset</h2><p>Tunna linnegardiner sl\xE4pper in ljuset men tar bort sk\xE4rpan. Speglar mitt emot f\xF6nster g\xF6r rummet ljusare.</p>
        <h2>Ljust tr\xE4 och mjuka material</h2><p>Ek, bj\xF6rk, lin och ull. Material som \xE4r fina att ta i och som \xE5ldras med v\xE4rdighet.</p>
        <h2>Lagom mycket</h2><p>F\xE4rre saker, men saker med en tydlig funktion och plats. Det \xE4r inte asketiskt, det \xE4r lugnt.</p>
        <h2>Ljus i lager n\xE4r m\xF6rkret kommer</h2><p>Flera sm\xE5 ljusk\xE4llor p\xE5 olika h\xF6jd i st\xE4llet f\xF6r en stark lampa i taket. Det \xE4r s\xE5 skandinaviska hem h\xE5ller v\xE4rmen under de m\xF6rka m\xE5naderna.</p>`,picks:["lysa-keramiklampa","dagsljus-linnegardin-2-pack","lin-kuddfodral"]},{slug:"varmt-vardagsrum",img:"assets/img/mag/vardagsrum-1200.webp",minutes:3,rooms:["vardagsrum"],title:"S\xE5 skapar du ett varmt och v\xE4lkomnande vardagsrum",lead:"Sm\xE5 \xE4ndringar i ljus och m\xF6blering kan \xE4ndra hur ett rum k\xE4nns.",body:`<p>Ett vardagsrum blir varmt av tre saker: ljuset, textilierna och hur m\xF6blerna st\xE5r. Inget av det kr\xE4ver en renovering.</p>
        <h2>Flytta in m\xF6blerna fr\xE5n v\xE4ggarna</h2><p>N\xE4r soffan och f\xE5t\xF6ljen st\xE5r n\xE4rmare varandra blir rummet en plats att umg\xE5s p\xE5, inte en korridor.</p>
        <h2>Tre ljuspunkter</h2><p>En lampa vid soffan, en p\xE5 en sk\xE4nk och en l\xE4gre i ett h\xF6rn. Varmt, d\xE4mpat ljus i \xF6gonh\xF6jd och ned\xE5t.</p>
        <h2>Textil i lager</h2><p>En pl\xE4d \xF6ver armst\xF6det, tv\xE5 kuddar i olika material och kanske en korg med fler filtar. Det \xE4r de mjuka sakerna som g\xF6r att man stannar kvar.</p>`,picks:["plad-ullblandning-havre","lysa-keramiklampa","lin-kuddfodral"]},{slug:"belysning-i-lager",img:"assets/img/rum/sovrum-efter-1344.webp",minutes:4,rooms:["vardagsrum","sovrum"],title:"Belysning i lager: s\xE5 blir hemmet mysigt p\xE5 kv\xE4llen",lead:"En taklampa r\xE4cker inte. Med tre ljusk\xE4llor p\xE5 olika h\xF6jd blir samma rum lugnt, varmt och l\xE4tt att vara i.",body:`<p>Det vanligaste felet i ett m\xF6rkt svenskt vinterhem \xE4r f\xF6r f\xE5 lampor. En stark taklampa lyser upp allt lika mycket, och d\xE5 k\xE4nns rummet platt. L\xF6sningen \xE4r att t\xE4nka i lager.</p>
        <h2>Lager 1: grundljuset</h2><p>Taklampan eller en golvlampa som ger ljus i hela rummet. Den beh\xF6vs n\xE4r du st\xE4dar eller letar efter n\xE5got, men den kan g\xE4rna vara sl\xE4ckt resten av kv\xE4llen.</p>
        <h2>Lager 2: ljus d\xE4r du g\xF6r n\xE5got</h2><p>En lampa vid l\xE4sf\xE5t\xF6ljen, p\xE5 nattduksbordet eller \xF6ver skrivbordet. Ljuset ska falla p\xE5 det du tittar p\xE5, inte i \xF6gonen. En sk\xE4rm i textil eller veckat tyg sprider ljuset mjukt.</p>
        <h2>Lager 3: st\xE4mningsljuset</h2><p>Sm\xE5, l\xE5ga ljusk\xE4llor som g\xF6r rummet levande: en lampa p\xE5 en hylla, en uppladdningsbar lampa p\xE5 f\xF6nsterb\xE4nken eller levande ljus p\xE5 bordet. De lyser inte upp mycket, men de g\xF6r att man vill stanna.</p>
        <h2>V\xE4lj varmt ljus</h2><p>Titta efter 2 700 kelvin eller l\xE4gre p\xE5 lampans f\xF6rpackning. Det ger det gula, varma ljuset som liknar en solnedg\xE5ng. Kallare ljus passar i badrummet och vid arbetsb\xE4nken, inte i soffan.</p>
        <h2>Prova innan du k\xF6per</h2><p>Det \xE4r sv\xE5rt att f\xF6rest\xE4lla sig en lampa i sitt eget rum. Ta en bild av rummet i Mitt rum och st\xE4ll in lampan d\xE4r, s\xE5 ser du storlek och stil innan du best\xE4mmer dig.</p>`,picks:["lysa-keramiklampa","svamp-uppladdningsbar-lampa","glob-bordslampa-opalglas","stilla-ljusstake-massing-2-pack"]},{slug:"litet-sovrum",img:"assets/img/rum/sovrum-1600.webp",minutes:4,rooms:["sovrum"],title:"Inred ett litet sovrum: sex s\xE4tt att f\xE5 det att k\xE4nnas st\xF6rre",lead:"Ljusa textilier, smart f\xF6rvaring och r\xE4tt ljus g\xF6r mer \xE4n kvadratmetrarna.",body:`<p>Ett litet sovrum beh\xF6ver inte k\xE4nnas tr\xE5ngt. Det handlar mindre om ytan och mer om hur mycket som syns p\xE5 en g\xE5ng.</p>
        <h2>1. Ljusa textilier i samma ton</h2><p>P\xE5slakan, gardiner och pl\xE4d i n\xE4rliggande ljusa f\xE4rger flyter ihop och g\xF6r att rummet upplevs st\xF6rre. Lin och bomull i havre, sand och vitt \xE4r l\xE4tta att kombinera.</p>
        <h2>2. Gardiner fr\xE5n tak till golv</h2><p>H\xE4ng gardinst\xE5ngen h\xF6gt och n\xE4ra taket och l\xE5t gardinerna n\xE5 golvet. F\xF6nstret ser st\xF6rre ut och takh\xF6jden k\xE4nns h\xF6gre.</p>
        <h2>3. F\xF6rvaring som syns, men lugnt</h2><p>Korgar med lock eller i fl\xE4tat material under s\xE4ngen och nattduksbordet samlar det l\xF6sa. Ett f\xE5tal korgar i samma material ser ordnat ut, m\xE5nga olika ser st\xF6kiga ut.</p>
        <h2>4. Ljus fr\xE5n sidan, inte bara uppifr\xE5n</h2><p>En lampa p\xE5 nattduksbordet ger ett varmt ljus i \xF6gonh\xF6jd och g\xF6r rummet mjukare p\xE5 kv\xE4llen. Det tar mindre plats \xE4n en golvlampa.</p>
        <h2>5. En sak p\xE5 v\xE4ggen</h2><p>En affisch eller en tavla ovanf\xF6r s\xE4ngen ger rummet en mittpunkt. Fler sm\xE5 saker splittrar och krymper v\xE4ggen.</p>
        <h2>6. Fri golvyta</h2><p>Ju mer golv som syns, desto st\xF6rre k\xE4nns rummet. V\xE4lj ett nattduksbord eller en hylla p\xE5 v\xE4ggen i st\xE4llet f\xF6r en byr\xE5 om det g\xE5r.</p>`,picks:["vila-paslakanset-linne","dagsljus-linnegardin-2-pack","flatad-forvaringskorg","lysa-keramiklampa"]},{slug:"hyresvanlig-inredning",img:"assets/img/rum/hall-1600.webp",minutes:3,rooms:["hall","vardagsrum"],title:"Hyresv\xE4nlig inredning: g\xF6r om utan att borra",lead:"Bor du i hyresr\xE4tt eller i andra hand? S\xE5 g\xF6r du hemmet personligt utan h\xE5l i v\xE4ggarna.",body:`<p>M\xE5nga vill inte, eller f\xE5r inte, borra i v\xE4ggarna. Det mesta som g\xF6r ett hem personligt g\xE5r \xE4nd\xE5 att l\xF6sa utan verktyg, och allt f\xF6ljer med n\xE4r du flyttar.</p>
        <h2>St\xE4ll tavlorna i st\xE4llet f\xF6r att h\xE4nga dem</h2><p>Luta en affisch med ram mot v\xE4ggen p\xE5 en hylla, en byr\xE5 eller direkt p\xE5 golvet. Flera ramar i olika storlek som lutar mot varandra ser genomt\xE4nkt ut, och du kan byta n\xE4r du vill.</p>
        <h2>Ljus utan sladdar</h2><p>En uppladdningsbar lampa kan st\xE5 d\xE4r det saknas uttag: p\xE5 hyllan i hallen, p\xE5 balkongbordet eller i bokhyllan. Ladda den p\xE5 dagen och l\xE5t den lysa p\xE5 kv\xE4llen.</p>
        <h2>En matta som ramar in</h2><p>En matta under soffbordet eller i hallen g\xF6r att ytan k\xE4nns som en egen plats. Jute och ull t\xE5l vardag och syns p\xE5 ett bra s\xE4tt.</p>
        <h2>Textil g\xF6r mest</h2><p>Gardiner, kuddar och en pl\xE4d \xE4ndrar ett rum mer \xE4n man tror, och det \xE4r det f\xF6rsta du packar n\xE4r du flyttar.</p>`,picks:["affisch-linje-ekram","svamp-uppladdningsbar-lampa","strand-jutematta","lin-kuddfodral"]}],t.articleBySlug=r=>t.ARTICLES.find(k=>k.slug===r)||null})();
